import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { id } from '../i18n/id';
import { en } from '../i18n/en';

// Product copy must not make the claims the research appraisal rules out
// (clinical validation, efficacy, suicide prevention, diagnosis, therapy,
// "care received" ...). The gates are generated by the research pipeline from
// docs/research/sela-relay (data/research/corpus/eval_fixtures/claim_gates.json).
type Gate = { id: string; patterns: string[]; forbidden_examples: string[]; allowed_examples: string[] };
const file = join(__dirname, '..', '..', '..', 'data', 'research', 'corpus', 'eval_fixtures', 'claim_gates.json');
const gates: Gate[] = JSON.parse(readFileSync(file, 'utf8')).gates;
const compiled = gates.map((g) => ({ ...g, res: g.patterns.map((p) => new RegExp(p, 'iu')) }));
const hits = (re: RegExp[], text: string) => re.some((r) => r.test(text));

describe('claim gates', () => {
  it('compile in JavaScript and behave as their own examples say', () => {
    expect(compiled.length).toBeGreaterThan(5);
    for (const g of compiled) {
      for (const ex of g.forbidden_examples) expect(hits(g.res, ex), `${g.id} should match: ${ex}`).toBe(true);
      for (const ex of g.allowed_examples) expect(hits(g.res, ex), `${g.id} should not match: ${ex}`).toBe(false);
    }
  });
  it('find no forbidden claim in any Indonesian or English UI string', () => {
    const problems: string[] = [];
    for (const [lang, dict] of [['id', id], ['en', en]] as const) {
      for (const [key, text] of Object.entries(dict)) {
        for (const g of compiled) if (hits(g.res, text)) problems.push(`${lang}:${key} [${g.id}] ${text}`);
      }
    }
    expect(problems).toEqual([]);
  });
});
